def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'

    # count recent outcomes of opponent
    recent = history[-10:] if n >= 10 else history
    opp_defects = sum(1 for (a, b) in recent if b == 'D')
    my_defects = sum(1 for (a, b) in recent if a == 'D')

    # Tit-for-tat with initial cooperation and slight forgiveness/retaliation
    last_opp = history[-1][1]
    last_me = history[-1][0]

    # If opponent has been mostly cooperative recently, cooperate
    if opp_defects == 0:
        return 'C'
    if opp_defects == 1 and n > 5:
        # occasional forgiveness
        if rng.random() < 0.7:
            return 'C'
        return 'D'

    if opp_defects >= 3:
        # retaliate but maybe test cooperation occasionally
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # default tit-for-tat
    if last_opp == 'D':
        return 'D'
    return 'C'

